static _R _endDrag(String method, Map<String, String> params) async {
  final pointer = int.tryParse(params['pointer'] ?? '');
  final x = double.tryParse(params['x'] ?? '');
  final y = double.tryParse(params['y'] ?? '');
  if (pointer == null || x == null || y == null) {
    return _error('pointer (int), x (double), and y (double) parameters required');
  }

  final binding = GestureBinding.instance;
  final tEnd = Duration(milliseconds: DateTime.now().millisecondsSinceEpoch);

  final position = Offset(x, y);

  binding.handlePointerEvent(
    PointerUpEvent(
      pointer: pointer,
      position: position,
      kind: PointerDeviceKind.mouse,
      timeStamp: tEnd,
    ),
  );
  binding.handlePointerEvent(
    PointerRemovedEvent(
      pointer: pointer,
      position: position,
      kind: PointerDeviceKind.mouse,
      timeStamp: tEnd,
    ),
  );

  return _ok({'ended': true, 'pointer': pointer});
}

